#!/usr/bin/env python3
"""Phone-only D01/C05/C06 contracts; Light360 RTL, targeted320 and directional LTR."""
import argparse, hashlib, http.server, json, subprocess, tempfile, threading
from pathlib import Path
from playwright.sync_api import sync_playwright
from browser_support import chromium_launch_options

ROOT=Path(__file__).resolve().parents[1]
class Handler(http.server.SimpleHTTPRequestHandler):
    def __init__(self,*a,**kw):super().__init__(*a,directory=str(ROOT),**kw)
    def log_message(self,*_):pass

def main():
    ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--out',type=Path);args=ap.parse_args()
    out=args.out or Path(tempfile.mkdtemp(prefix='mobile-capabilities-'));out.mkdir(parents=True,exist_ok=True)
    server=http.server.ThreadingHTTPServer(('127.0.0.1',0),Handler);threading.Thread(target=server.serve_forever,daemon=True).start()
    base=f'http://127.0.0.1:{server.server_port}';checks=[];errors=[];measurements=[]
    def check(name,ok,detail=None):
        checks.append(dict(name=name,passed=bool(ok),detail=detail));print(('PASS ' if ok else 'FAIL ')+name,flush=True)
    with sync_playwright() as pw:
        browser=pw.chromium.launch(**chromium_launch_options());version=browser.version
        p=browser.new_page(viewport={'width':360,'height':780},is_mobile=True,has_touch=True,color_scheme='light',locale='ar',reduced_motion='reduce')
        p.set_default_timeout(6000)
        p.on('pageerror',lambda e:errors.append(str(e)));p.on('response',lambda r:errors.append(str(r.status)+' '+r.url) if r.status>=400 else None)
        def ev(js):return p.evaluate(js)
        def go(name):
            p.goto(base+'/previews/mobile-capabilities/'+name+'.html',wait_until='networkidle');ev('document.fonts.ready')
        def geometry(sel,name,controls=False):
            d=p.locator(sel).evaluate('''(e,controls)=>{let r=e.getBoundingClientRect();return {left:r.left,right:r.right,width:r.width,height:r.height,viewport:innerWidth,scroll:document.documentElement.scrollWidth,bad:controls?[...e.querySelectorAll('button')].filter(b=>b.getClientRects().length&&!b.closest('[hidden]')).map(b=>({w:b.getBoundingClientRect().width,h:b.getBoundingClientRect().height})).filter(b=>b.w<47.9||b.h<47.9):[]}}''',controls)
            measurements.append(dict(name=name,**d));check(name,d['left']>=-1 and d['right']<=d['viewport']+1 and d['scroll']==d['viewport'] and not d['bad'],d)
        def shot(sel,name):p.locator(sel).screenshot(path=str(out/(name+'.png')))
        # D01: synchronous consent preserves all state when prevented.
        go('protected-form');p.locator('#open-guarded-form').tap()
        ev("window.layer=document.querySelector('#guarded-form');window.requests=[];window.closeCount=0;window.guard=new AbortController();layer.addEventListener('micro-navigation:close-request',e=>{requests.push({reason:e.detail.reason,trigger:e.detail.trigger&&e.detail.trigger.id});e.preventDefault()},{signal:guard.signal});layer.addEventListener('micro-navigation:closed',()=>closeCount++);document.querySelector('#sample-note').focus();window.before=JSON.stringify({hidden:layer.hidden,inert:layer.inert,active:document.activeElement.id,overflow:document.body.style.overflow,main:document.querySelector('main').inert})")
        check('Programmatic request is synchronously vetoed without state/focus/scroll change',ev("MicroNavigation.requestClose(layer)===false&&before===JSON.stringify({hidden:layer.hidden,inert:layer.inert,active:document.activeElement.id,overflow:document.body.style.overflow,main:document.querySelector('main').inert})&&closeCount===0"))
        p.keyboard.press('Escape');p.locator('#guarded-form [data-layer-close]').tap();p.locator('#form-backdrop').tap(position={'x':5,'y':30})
        check('Escape, close button and backdrop request the documented reasons once',ev("requests.map(x=>x.reason).join(',')==='programmatic-request,escape,close-button,backdrop'&&!layer.hidden&&closeCount===0"),ev('requests'))
        ev("layer.dataset.backdrop='keep';window.n=requests.length");p.locator('#form-backdrop').tap(position={'x':5,'y':30})
        check('Backdrop keep sends no request',ev('requests.length===n&&!layer.hidden'));ev("layer.dataset.backdrop='close'")
        ev("window.reentrant=null;layer.addEventListener('micro-navigation:close-request',()=>{reentrant=MicroNavigation.requestClose(layer)},{once:true});MicroNavigation.requestClose(layer)")
        check('Reentrant request is ignored rather than dispatched twice',ev('reentrant===false&&requests.length===n+1'))
        ev("guard.abort();window.accepted=MicroNavigation.requestClose(layer)")
        check('Absent guard keeps normal closing, returns true and restores opener',ev("accepted&&layer.hidden&&closeCount===1&&document.activeElement.id==='open-guarded-form'&&document.body.style.overflow!== 'hidden'"))
        check('Closed, invalid and null requests are no-ops',ev('!MicroNavigation.requestClose(layer)&&!MicroNavigation.requestClose(null)&&closeCount===1'))
        p.locator('#open-guarded-form').tap();p.locator('#sample-note').fill('نص يبقى عند متابعة التعديل');p.keyboard.press('Escape')
        check('Dirty policy is supplied by the consumer, opening one named confirmation',ev("!document.querySelector('#discard-confirm').hidden&&!layer.hidden&&layer.inert&&document.querySelector('#discard-confirm').getAttribute('role')==='alertdialog'"))
        check('A request cannot dismiss an underlying layer past its top confirmation',ev('MicroNavigation.requestClose(layer)===false&&!layer.hidden'))
        geometry('#discard-confirm','Confirmation controls360',True);shot('#discard-confirm','guard-confirm360')
        p.locator('#keep-editing').tap()
        check('Keep editing preserves input, restores focus and maintains the parent lock',ev("document.querySelector('#discard-confirm').hidden&&!layer.hidden&&document.querySelector('#sample-note').value==='نص يبقى عند متابعة التعديل'&&document.activeElement.id==='sample-note'&&document.body.style.overflow==='hidden'"))
        p.keyboard.press('Escape');p.locator('#discard-sample').tap()
        check('Discard closes confirmation then form once and restores page',ev("layer.hidden&&document.querySelector('#discard-confirm').hidden&&document.querySelector('#sample-note').value===''&&document.activeElement.id==='open-guarded-form'&&document.body.style.overflow!=='hidden'"))
        p.locator('#open-guarded-form').tap();p.locator('#sample-note').fill('قيمة معتمدة محليًا');ev('window.n=requests.length');p.locator('#accept-sample').tap()
        check('Explicit accepted-result command does not ask for confirmation again',ev('layer.hidden&&requests.length===n&&document.querySelector("#discard-confirm").hidden'))
        p.locator('#open-guarded-form').tap();ev("layer.addEventListener('micro-navigation:close-request',e=>{e.preventDefault();MicroNavigation.disconnect(layer)},{once:true});window.result=MicroNavigation.requestClose(layer)")
        check('Cleanup during a veto cannot be prevented or leave stale scroll/inert',ev("result===false&&layer.hidden&&document.body.style.overflow!=='hidden'&&!document.querySelector('main').inert"))
        go('protected-form');p.locator('#open-guarded-form').tap()
        ev("window.layer=document.querySelector('#guarded-form');window.n=0;layer.addEventListener('micro-navigation:close-request',()=>{n++;MicroNavigation.openLayer(layer)},{once:true});window.result=MicroNavigation.requestClose(layer)")
        check('Reopening during dispatch invalidates the old request generation',ev('!result&&!layer.hidden&&n===1'))
        ev('MicroNavigation.closeLayer(layer)')
        p.emulate_media(reduced_motion='no-preference');p.locator('#open-guarded-form').tap()
        ev('MicroNavigation.closeLayer(layer);MicroNavigation.disconnect(layer)');p.wait_for_timeout(350)
        check('Direct Navigation cleanup during closing also hides its pending backdrop',ev("layer.hidden&&document.querySelector('#form-backdrop').hidden&&document.body.style.overflow!=='hidden'&&!document.querySelector('main').inert"))
        p.emulate_media(reduced_motion='reduce')
        # C05: one mobile layer controller, native buttons, no desktop menu role.
        go('actions');ev("window.sheet=document.querySelector('#sample-actions');window.actions=[];window.order=[];sheet.addEventListener('micro-actions:request',e=>{actions.push(e.detail);order.push('request')});sheet.addEventListener('micro-navigation:closed',()=>order.push('closed'));MicroActionSheet.init(sheet);MicroActionSheet.init(sheet)")
        p.locator('#row-actions').tap();geometry('#sample-actions','Action targets360',True);shot('#sample-actions','actions360')
        check('Mobile action list uses a named dialog and native commands, without menu/listbox roles',ev("sheet.getAttribute('role')==='dialog'&&!!sheet.getAttribute('aria-labelledby')&&!sheet.querySelector('[role=menu],[role=menuitem],[role=option]')&&sheet.contains(document.activeElement)"))
        p.keyboard.press('Shift+Tab');last=ev("document.activeElement.getAttribute('data-action-id')==='delete'");p.keyboard.press('Tab')
        check('Phone Tab stays trapped and skips the disabled command',last and ev("document.activeElement===sheet.querySelector('[data-layer-close]')"))
        ev("sheet.querySelector('[data-action-id=unavailable]').click()")
        check('Disabled command does not close or dispatch',ev('!sheet.hidden&&actions.length===0'))
        p.locator('[data-action-id=copy]').tap()
        check('Row command emits exactly once after closed and restores its opener',ev("sheet.hidden&&actions.length===1&&actions[0].id==='copy'&&actions[0].contextKey==='row-example'&&order.join(',')==='closed,request'&&document.activeElement.id==='row-actions'"))
        p.locator('#card-actions').tap();p.locator('[data-action-id=inspect]').tap()
        check('Same sheet receives a fresh card context',ev("actions.length===2&&actions[1].contextKey==='card-example'&&document.activeElement.id==='card-actions'"))
        p.locator('#row-actions').tap();ev("window.veto=new AbortController();sheet.addEventListener('micro-navigation:close-request',e=>e.preventDefault(),{signal:veto.signal})");p.locator('[data-action-id=delete]').tap()
        check('Denied close never emits a command',ev('actions.length===2&&!sheet.hidden'))
        ev('veto.abort()');p.locator('[data-action-id=delete]').tap();check('Retry after veto can emit exactly one command',ev("actions.length===3&&actions[2].id==='delete'"))
        p.locator('.demo-tools > summary').tap();p.locator('#toggle-empty-actions').tap();p.locator('#row-actions').tap()
        check('Empty consumer state remains readable with an explicit Cancel',p.locator('[data-actions-empty]').is_visible() and not p.locator('.m-action-sheet__list').is_visible() and p.locator('#sample-actions [data-layer-close]').is_visible())
        ev("sheet.querySelector('[data-action-id=copy]').click()")
        check('Hidden commands cannot dispatch programmatically',ev('actions.length===3&&!sheet.hidden'))
        p.locator('#sample-actions [data-layer-close]').tap();check('Cancel sends no command',ev('actions.length===3'))
        p.locator('#toggle-empty-actions').tap();p.locator('#row-actions').tap()
        p.locator('[data-action-id=inspect]').focus();p.keyboard.press('Enter');check('Phone keyboard activation retains native button behavior',ev('actions.length===4'))
        ev("window.copy=sheet.cloneNode(true);copy.id='cloned-actions';copy.querySelector('.m-layer__title').id='cloned-title';copy.setAttribute('aria-labelledby','cloned-title');copy.removeAttribute('data-backdrop-id');document.body.append(copy);window.cloned=[];copy.addEventListener('micro-actions:request',e=>cloned.push(e.detail));MicroActionSheet.init(copy);MicroActionSheet.init(copy);MicroActionSheet.open(copy,{contextKey:'opaque\"<>',trigger:document.querySelector('#row-actions')});copy.querySelector('[data-action-id=copy]').click()")
        check('Cloned list binds once with its own opaque context',ev("cloned.length===1&&cloned[0].contextKey==='opaque\"<>'&&actions.length===4"))
        ev("MicroActionSheet.open(copy);window.stale=copy.querySelector('[data-action-id=copy]');MicroActionSheet.disconnect(copy);stale.click()")
        check('Disconnect aborts stale commands and releases the layer',ev("cloned.length===1&&copy.hidden&&document.body.style.overflow!=='hidden'"))
        ev('MicroActionSheet.init(copy);MicroActionSheet.open(copy);copy.querySelector("[data-action-id=inspect]").click()')
        check('Reconnect initializes a clean lifetime once',ev('cloned.length===2&&copy.hidden'))
        ev('MicroActionSheet.disconnect(copy);copy.remove()')
        check('Detached sheets cannot lock the page',ev("!MicroActionSheet.open(document.createElement('div'))&&document.body.style.overflow!=='hidden'"))
        p.set_viewport_size({'width':320,'height':780});p.locator('#card-actions').tap()
        ev("sheet.querySelector('[data-action-id=inspect]').textContent='تفاصيل الإجراء ذي التسمية العربية الطويلة دون اختصار أو قص'")
        geometry('#sample-actions','Narrow320 long action labels',True);shot('#sample-actions','actions320');p.locator('#sample-actions [data-layer-close]').tap()
        p.set_viewport_size({'width':360,'height':780});p.locator('#row-actions').tap()
        ev("window.list=sheet.querySelector('.m-action-sheet__list');for(let i=0;i<20;i++){let li=list.firstElementChild.cloneNode(true);li.dataset.extra='true';li.querySelector('button').dataset.actionId='extra-'+i;list.append(li)}")
        d=ev("(()=>{let body=sheet.querySelector('.m-layer__body'),r=sheet.querySelector('[data-layer-close]').getBoundingClientRect(),s=sheet.getBoundingClientRect();return {scroll:body.scrollHeight,client:body.clientHeight,top:s.top,bottom:s.bottom,cancelTop:r.top,cancelBottom:r.bottom}})()")
        check('Long list scrolls inside the mobile sheet while Cancel stays reachable',d['scroll']>d['client'] and d['top']>=0 and d['bottom']<=780 and d['cancelTop']>=d['top'] and d['cancelBottom']<=780,d)
        ev("sheet.querySelectorAll('[data-extra]').forEach(e=>e.remove())");p.locator('#sample-actions [data-layer-close]').tap()
        p.set_viewport_size({'width':360,'height':780});ev("document.documentElement.dir='ltr'");p.locator('#row-actions').tap();geometry('#sample-actions','Directional LTR actions360',True);p.locator('#sample-actions [data-layer-close]').tap()
        # Real transitions: commands wait for closed; reopen and cleanup cancel them.
        p.emulate_media(reduced_motion='no-preference');p.locator('#row-actions').tap();p.wait_for_timeout(300)
        ev("window.n=actions.length;order.length=0;sheet.querySelector('[data-action-id=copy]').click();sheet.querySelector('[data-action-id=copy]').click()")
        check('Animated close does not emit early or accept repeat taps',ev("actions.length===n&&sheet.hasAttribute('data-closing')&&!MicroNavigation.requestClose(sheet)"))
        p.wait_for_function('sheet.hidden');check('Animated close emits one intent after completion',ev('actions.length===n+1'))
        check('Normal motion preserves observable closed before request ordering',ev("order.join(',')==='closed,request'"),ev('order'))
        p.locator('#row-actions').tap();p.wait_for_timeout(300)
        ev("window.n=actions.length;sheet.querySelector('[data-action-id=copy]').click();MicroActionSheet.open(sheet,{contextKey:'new-context'})")
        p.wait_for_timeout(350);check('Reopen cancels a stale pending action and leaves the new layer open',ev("actions.length===n&&!sheet.hidden&&document.body.style.overflow==='hidden'"))
        ev("sheet.querySelector('[data-action-id=copy]').click();MicroActionSheet.disconnect(sheet)");p.wait_for_timeout(350)
        check('Cleanup during animation never dispatches or leaves a backdrop or page lock',ev("actions.length===n&&sheet.hidden&&document.querySelector('#actions-backdrop').hidden&&document.body.style.overflow!=='hidden'&&!document.querySelector('main').inert"))
        p.emulate_media(reduced_motion='reduce')
        p.locator('#row-actions').tap()
        ev("window.n=actions.length;sheet.addEventListener('micro-navigation:closed',()=>MicroActionSheet.open(sheet,{contextKey:'replacement'}),{once:true});sheet.querySelector('[data-action-id=copy]').click()")
        check('Reopen during closed cancels the queued intent instead of targeting new context',ev("actions.length===n&&!sheet.hidden"))
        ev('MicroActionSheet.disconnect(sheet)')
        # C06: scope is explicit, state is read-only and setters sync at the owner.
        go('calendar-summary');ev("window.cal=MicroOrderSchedule.init(document.querySelector('#summary-calendar'));window.stateEvents=0;document.querySelector('#summary-calendar').addEventListener('order-schedule:state-change',()=>stateEvents++)")
        check('Initial external summary names selected day with count2 and unit',ev("document.querySelector('[data-context-title]').textContent==='طلبات اليوم المحدد'&&document.querySelector('[data-context-period]').textContent==='2026-11-13'&&document.querySelector('[data-context-value]').textContent==='2'&&!document.querySelector('[data-context-unit]').hidden&&!document.querySelector('#summary-calendar').contains(document.querySelector('#calendar-context'))"))
        ev("window.calendarDOM=document.querySelector('#summary-calendar').innerHTML");p.locator('#summary-scope').select_option('month')
        check('Changing summary scope does not write Calendar DOM or state',ev("calendarDOM===document.querySelector('#summary-calendar').innerHTML&&stateEvents===0&&document.querySelector('[data-context-period]').textContent==='2026-11'"))
        p.locator('#summary-calendar [data-ocal-action=next-month]').tap()
        check('Month navigation updates monthly count while keeping selected day independent',ev("cal.getState().selectedDate==='2026-11-13'&&cal.getState().displayedMonth==='2026-12'&&document.querySelector('[data-context-period]').textContent==='2026-12'&&document.querySelector('[data-context-value]').textContent==='1'"))
        p.locator('#summary-scope').select_option('day');check('Selected-day summary does not silently follow displayed month',ev("document.querySelector('[data-context-period]').textContent==='2026-11-13'&&document.querySelector('[data-context-value]').textContent==='2'"))
        p.locator('#summary-calendar [data-ocal-date="2026-12-02"]').tap()
        check('User date selection updates summary from public state',ev("document.querySelector('[data-context-period]').textContent==='2026-12-02'&&document.querySelector('[data-context-value]').textContent==='1'"))
        p.locator('#summary-calendar [data-ocal-date="2026-12-03"]').tap()
        check('A selected day without matching records is a known zero',ev("document.querySelector('[data-context-period]').textContent==='2026-12-03'&&document.querySelector('[data-context-value]').textContent==='0'"))
        p.locator('.demo-tools > summary').click();ev('window.n=stateEvents');p.locator('#set-summary-date').click()
        check('Consumer explicitly syncs a silent setter without inventing events',ev('stateEvents===n&&document.querySelector("[data-context-period]").textContent==="2026-12-02"'))
        geometry('#calendar-context','External context360');shot('#calendar-context','calendar-context360');shot('#summary-calendar','calendar360')
        p.locator('#summary-state').select_option('loading');check('Loading never shows a stale number as a new period reading',ev("document.querySelector('#calendar-context').getAttribute('aria-busy')==='true'&&document.querySelector('[data-context-value]').textContent==='جارٍ التحديث…'&&document.querySelector('[data-context-unit]').hidden"))
        p.locator('#summary-state').select_option('error');check('Missing reading after error is not a fake zero',ev("document.querySelector('[data-context-value]').textContent==='(غير متاح)'&&document.querySelector('#calendar-context').getAttribute('aria-busy')==='false'"))
        p.locator('#summary-state').select_option('empty');check('Known empty source is an honest zero with its unit',ev("document.querySelector('[data-context-value]').textContent==='0'&&!document.querySelector('[data-context-unit]').hidden"))
        p.locator('#summary-state').select_option('ready');check('Recovery replaces empty reading using current scope',ev("document.querySelector('[data-context-value]').textContent==='1'"))
        p.locator('#destroy-summary').click();ev("document.querySelector('#set-summary-date').click();document.querySelector('#summary-scope').dispatchEvent(new Event('change'))")
        check('Consumer cleanup aborts all listeners before Calendar destruction',ev("document.querySelector('#summary-consumer').hidden&&!document.querySelector('#summary-end').hidden&&document.querySelector('#summary-calendar').children.length===0"))
        check('No browser or resource errors',not errors,errors)
        browser.close()
    server.shutdown()
    paths=['components/navigation/navigation.js','components/navigation/action-sheet.js','components/navigation/action-sheet.css','previews/mobile-capabilities/form.js','previews/mobile-capabilities/actions.js','previews/mobile-capabilities/calendar-summary.js']
    report=dict(commitAtRun=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),workingTree=True,physicalDevice=False,browser=version,scope='Phone-only Light360x780 RTL/touch; targeted320 actions; directional360 LTR; normal/reduced motion; no Dark/desktop layout',passed=sum(c['passed'] for c in checks),failed=sum(not c['passed'] for c in checks),checks=checks,measurements=measurements,sourceSha256={n:hashlib.sha256((ROOT/n).read_bytes()).hexdigest() for n in paths})
    (out/'results.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');print(f"Mobile capabilities: {report['passed']} PASS / {report['failed']} FAIL");return bool(report['failed'])
if __name__=='__main__':raise SystemExit(main())
